+async function findPackagesInDir(dir: string): Promise<{ name: string; path: string }[]> {
+	try {
+		const entries = await readdir(dir, { withFileTypes: true });
+		const packages = [];
+
+		for (const entry of entries) {
+			if (!entry.isDirectory()) continue;
+
