+    position.lineNumber,
+    position.column,
+  );
+
+  let suggestions: monaco.languages.CompletionItem[] = [];
+
+  switch (context.position) {
+    case 'method':
+      suggestions = provideMethodCompletions();
+      break;
+    case 'path':
+      suggestions = providePathCompletions(context, range);
+      break;
