+const MANAGED_RELAY_URL = "wss://api.phodex.app/relay";
+const MAX_LEGACY_RELAY_SESSION_COUNT = 4;
+const MAX_QUEUED_OUTBOUND_APPLICATION_MESSAGES = 256;
