+    workspacePath: null,
+    relaySource: "managed",
+    relaySourceMessage: "Cowork-managed remote access state has not been loaded yet.",
+    relayServiceStatus: "running",
+    relayServiceMessage: "Cowork Desktop manages the relay session directly.",
+    relayServiceUpdatedAt: null,
+    relayUrl: null,
