+    await new Promise<void>((resolve, reject) => {
+      const socket = this.createRelaySocket(relaySessionUrl, {
+        "x-role": "mac",
+        "x-notification-secret": this.notificationSecret ?? "",
+        ...this.buildMacRegistrationHeaders(),
